/* ================== PARAMETERS (SSMS) ================== */
DECLARE @FromDate DATE = '2026-01-01';
DECLARE @ToDate   DATE = '2026-12-31';

SELECT     /* 0. Branch Info (THÊM CỘT TÊN CHI NHÁNH TẠI ĐÂY) */    ISNULL(T2.[BPLName], N'Trụ sở chính') AS [Branch Name],    /* 1. Business Partner & Remarks */    T1.[CardCode] AS [Customer Code],    T1.[CardName] AS [Customer Name],    T1.[Comments] AS [SO Remarks],    /* 2. Item & UoM Info */    T0.[ItemCode] AS [Item Code],    T0.[Dscription] AS [Item Description],    T0.[unitMsr] AS [Sales UoM],      T0.[unitMsr2] AS [Inventory UoM],     /* 3. Sales Order (SO) */    T1.[DocNum] AS [SO Doc. No.],    T1.[NumAtCard] AS [Customer PO No.],    T1.[DocDate] AS [SO Posting Date],               T0.[ShipDate] AS [Planned Ship Date],            T0.[Quantity] AS [Ordered Qty],        T1.[DocCur] AS [Currency],    T0.[Price] AS [Unit Price],     T0.[VatPrcnt] AS [VAT %],       CASE WHEN T1.[DocCur] = 'VND' THEN T0.[LineTotal] ELSE T0.[TotalFrgn] END AS [SO Line Total],    CASE WHEN T1.[DocCur] = 'VND' THEN T0.[VatSum] ELSE T0.[VatSumFrgn] END AS [SO VAT Amount],    /* 4. Delivery (Xuất kho) */    ISNULL(Del_Std.[DocNum], Del_Res.[DocNum]) AS [Delivery Doc. No.],    ISNULL(Del_Std.[DocDate], Del_Res.[DocDate]) AS [Delivery Posting Date],    ISNULL(Del_Std.[Quantity], Del_Res.[Quantity]) AS [Delivered Qty],    ISNULL(Del_Std.[WhsCode], Del_Res.[WhsCode]) AS [Whs Code],    /* 5. A/R Invoice (Hóa đơn bán) */    ISNULL(AR_Std.[DocNum], AR_Dir.[DocNum]) AS [AR Inv. Doc. No.],    ISNULL(AR_Std.[NumAtCard], AR_Dir.[NumAtCard]) AS [AR Inv. Customer Ref.],    ISNULL(AR_Std.[DocDate], AR_Dir.[DocDate]) AS [AR Inv. Posting Date],         ISNULL(        CASE WHEN AR_Std.[DocCur] = 'VND' THEN AR_Std.[LineTotal] ELSE AR_Std.[TotalFrgn] END,        CASE WHEN AR_Dir.[DocCur] = 'VND' THEN AR_Dir.[LineTotal] ELSE AR_Dir.[TotalFrgn] END    ) AS [AR Inv. Line Total],    ISNULL(        CASE WHEN AR_Std.[DocCur] = 'VND' THEN AR_Std.[VatSum] ELSE AR_Std.[VatSumFrgn] END,        CASE WHEN AR_Dir.[DocCur] = 'VND' THEN AR_Dir.[VatSum] ELSE AR_Dir.[VatSumFrgn] END    ) AS [AR Inv. VAT Amount],        /* 6. Document Flow Status */    CASE         WHEN AR_Std.[DocEntry] IS NOT NULL THEN 'SO -> Delivery -> AR Invoice'        WHEN Del_Res.[DocEntry] IS NOT NULL THEN 'SO -> AR Reserve -> Delivery'        WHEN AR_Dir.[DocEntry] IS NOT NULL THEN 'SO -> AR Invoice (Direct)'        WHEN Del_Std.[DocEntry] IS NOT NULL THEN 'SO -> Delivery (Pending AR)'        ELSE 'SO Only (Open)'    END AS [Document Flow]FROM [dbo].[RDR1] T0 INNER JOIN [dbo].[ORDR] T1 ON T0.[DocEntry] = T1.[DocEntry]/* [THÊM JOIN]: Lấy thông tin Chi nhánh từ Header Đơn bán hàng */LEFT JOIN [dbo].[OBPL] T2 ON T1.[BPLId] = T2.[BPLId]/* =========================================================   NHÁNH 1: LUỒNG CHUẨN ========================================================= */LEFT JOIN (    SELECT D1.DocEntry, D1.LineNum, D1.BaseEntry, D1.BaseLine, D1.BaseType, D1.Quantity, D1.WhsCode, D0.DocNum, D0.DocDate    FROM DLN1 D1 INNER JOIN ODLN D0 ON D1.DocEntry = D0.DocEntry WHERE D0.CANCELED = 'N') Del_Std ON Del_Std.BaseEntry = T0.DocEntry AND Del_Std.BaseLine = T0.LineNum AND Del_Std.BaseType = 17 LEFT JOIN (    SELECT D1.DocEntry, D1.LineNum, D1.BaseEntry, D1.BaseLine, D1.BaseType, D1.LineTotal, D1.TotalFrgn, D1.VatSum, D1.VatSumFrgn, D0.DocNum, D0.DocDate, D0.NumAtCard, D0.DocCur    FROM INV1 D1 INNER JOIN OINV D0 ON D1.DocEntry = D0.DocEntry WHERE D0.CANCELED = 'N') AR_Std ON AR_Std.BaseEntry = Del_Std.DocEntry AND AR_Std.BaseLine = Del_Std.LineNum AND AR_Std.BaseType = 15/* =========================================================   NHÁNH 2: LUỒNG TRỰC TIẾP / BẢO LƯU ========================================================= */LEFT JOIN (    SELECT D1.DocEntry, D1.LineNum, D1.BaseEntry, D1.BaseLine, D1.BaseType, D1.LineTotal, D1.TotalFrgn, D1.VatSum, D1.VatSumFrgn, D0.DocNum, D0.DocDate, D0.NumAtCard, D0.DocCur    FROM INV1 D1 INNER JOIN OINV D0 ON D1.DocEntry = D0.DocEntry WHERE D0.CANCELED = 'N') AR_Dir ON AR_Dir.BaseEntry = T0.DocEntry AND AR_Dir.BaseLine = T0.LineNum AND AR_Dir.BaseType = 17LEFT JOIN (    SELECT D1.DocEntry, D1.LineNum, D1.BaseEntry, D1.BaseLine, D1.BaseType, D1.Quantity, D1.WhsCode, D0.DocNum, D0.DocDate    FROM DLN1 D1 INNER JOIN ODLN D0 ON D1.DocEntry = D0.DocEntry WHERE D0.CANCELED = 'N') Del_Res ON Del_Res.BaseEntry = AR_Dir.DocEntry AND Del_Res.BaseLine = AR_Dir.LineNum AND Del_Res.BaseType = 13/* TỐI ƯU CÚ PHÁP SAP B1 CHO THAM SỐ NGÀY */WHERE T1.[DocDate] >= @FromDate AND T1.[DocDate] <= @ToDate AND T1.[CANCELED] = 'N' ORDER BY T1.[DocNum], T0.[LineNum]